describe('enc / pairEncode / formEncode', () => {
  it('encodes only scalars — an object would send [object Object]', () => {
    expect(enc('a b')).toBe('a%20b');
    expect(enc(42)).toBe('42');
    expect(enc(true)).toBe('true');
    expect(enc(null)).toBe('');
    expect(enc(undefined)).toBe('');
    expect(enc({ a: 1 })).toBe('');
  });
  it('joins an array param the way a multi-select is mockSent', () => {
    expect(enc(['a', 'b'])).toBe('a%2Cb');
  });
  it('drops absent and empty fields, keeps the order given', () => {
    const vars = { a: '1', b: '', c: null, d: 'x y' };
    expect(pairEncode(vars, ['a', 'b', 'c', 'd'], '&')).toBe('a=1&d=x y');
    expect(formEncode(vars, ['a', 'd'])).toBe('a=1&d=x%20y');
  });
  it('joins a cookie with its own separator', () => {
    expect(pairEncode({ a: '1', b: '2' }, ['a', 'b'], '; ')).toBe('a=1; b=2');
  });
  it('is empty when nothing is set', () => {
    expect(formEncode({ a: '' }, ['a'])).toBe('');
    expect(formEncode({}, [])).toBe('');
  });
});

describe('setByPath', () => {
  it('builds the nested shape a dotted body field describes', () => {
    const body: Record<string, any> = {};
    setByPath(body, 'customer.name.first', 'Ada');
    setByPath(body, 'customer.name.last', 'Lovelace');
    setByPath(body, 'amount', 10);
    expect(body).toEqual({ customer: { name: { first: 'Ada', last: 'Lovelace' } }, amount: 10 });
  });
  it('skips undefined so an unset field is absent, not null', () => {
    const body: Record<string, any> = {};
    setByPath(body, 'a.b', undefined);
    expect(body).toEqual({});
  });
  it('replaces a non-object on the way down instead of throwing', () => {
    const body: Record<string, any> = { a: 'scalar' };
    setByPath(body, 'a.b', 1);
    expect(body.a.b).toBe(1);
  });
});

describe('keepStatus', () => {
  it('carries the HTTP status across a parse, without becoming a visible field', () => {
    const original: Record<string, unknown> = {};
    Object.defineProperty(original, '__status', { value: 201, enumerable: false });
    const parsed = keepStatus({ id: 1 }, original);
    expect(JSON.stringify(parsed)).toBe('{"id":1}');
    expect((parsed as { __status?: number }).__status).toBe(201);
  });
  it('leaves a primitive alone', () => {
    expect(keepStatus(5 as never, {})).toBe(5);
  });
});

describe('newIdempotencyKey', () => {
  it('is RFC-4122 v4 shaped and different every time', () => {
    const a = newIdempotencyKey();
    const b = newIdempotencyKey();
    expect(a).toMatch(/^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/);
    expect(a).not.toBe(b);
  });
});

