describe('apiFetch', () => {
  beforeEach(() => {
    mockSent.length = 0;
    mockReply = { data: { id: 1 }, status: 200 };
    clearTokenRefCache();
  });

  it('sends method, path and query, and returns the parsed data', async () => {
    const out = await apiFetch('https://api.test/', { method: 'get', path: '/things', query: { q: 'x' } });
    expect(out).toEqual({ id: 1 });
    expect(mockSent[0]!.method).toBe('get');
    expect(mockSent[0]!.url).toBe('/things');
    expect(mockSent[0]!.params).toEqual({ q: 'x' });
  });
  it('drops empty query and header entries rather than sending blanks', async () => {
    await apiFetch('https://api.test', { method: 'get', path: '/x', query: { a: '', b: 'y' }, headers: { h: undefined } });
    expect(mockSent[0]!.params).toEqual({ b: 'y' });
    expect(mockSent[0]!.headers).not.toHaveProperty('h');
  });
  it('sends an Idempotency-Key on a mutation and never on a GET', async () => {
    await apiFetch('https://api.test', { method: 'post', path: '/pay', idempotencyKey: 'key-1' });
    expect(mockSent[0]!.headers['Idempotency-Key']).toBe('key-1');
    mockSent.length = 0;
    await apiFetch('https://api.test', { method: 'get', path: '/pay', idempotencyKey: 'key-1' });
    expect(mockSent[0]!.headers).not.toHaveProperty('Idempotency-Key');
  });
  it('stamps the real status onto an object body', async () => {
    mockReply = { data: { id: 2 }, status: 201 };
    const out = await apiFetch<Record<string, unknown>>('https://api.test', { method: 'post', path: '/x' });
    expect((out as { __status?: number }).__status).toBe(201);
  });
  it('turns a transport failure into an AppError, never an axios error', async () => {
    mockReply = Object.assign(new Error('Request failed'), { response: { status: 500, data: 'boom' } });
    await expect(apiFetch('https://api.test', { method: 'get', path: '/x' })).rejects.toBeInstanceOf(AppError);
  });
  it('maps a 401 to the auth kind so the caller can sign the user out', async () => {
    mockReply = Object.assign(new Error('nope'), { response: { status: 401, data: '' } });
    await expect(apiFetch('https://api.test', { method: 'get', path: '/x' })).rejects.toMatchObject({ kind: 'auth' });
  });
  it('maps a 404 to notFound', async () => {
    mockReply = Object.assign(new Error('gone'), { response: { status: 404, data: '' } });
    await expect(apiFetch('https://api.test', { method: 'get', path: '/x' })).rejects.toMatchObject({ kind: 'notFound' });
  });
});
